@import url('https://fonts.googleapis.com/css2?family=Familjen+Grotesk:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Inter Milan DNA — nerazzurri serpent night, biscione gradient */
.theme-inter-milan {
  --bg: oklch(0.185 0.030 268.4);
  --surface: oklch(0.227 0.042 268.9);
  --surface-2: oklch(0.272 0.055 269.4);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.673 0.049 271.4);
  --accent: oklch(0.543 0.171 260.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.731 0.115 85.0);
  --line: oklch(1 0 0 / 13%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Familjen Grotesk", sans-serif;
  --font-body: "Familjen Grotesk", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-inter-milan h1,
.theme-inter-milan h2,
.theme-inter-milan h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-inter-milan { --font-ui: var(--font-display); }
.theme-inter-milan h1, .theme-inter-milan h2 { text-transform: uppercase; }
.theme-inter-milan button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-inter-milan { background-image: repeating-linear-gradient(115deg, oklch(0.35 0.1 260 / 22%) 0 42px, transparent 42px 84px); }
.theme-inter-milan h1 { background: linear-gradient(95deg, #a9c6ff, #4a86e8); -webkit-background-clip: text; background-clip: text; color: transparent; }

/* depth */
.theme-inter-milan thead th { background: linear-gradient(115deg, oklch(0.25 0.06 264), oklch(0.21 0.04 269)); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 2px solid oklch(0.62 0.16 259); }
.theme-inter-milan td { border-bottom: 1px solid var(--line); }
.theme-inter-milan tbody tr:hover { background: oklch(0.543 0.171 260.5 / 16%); }
.theme-inter-milan a { color: oklch(0.70 0.13 258); text-underline-offset: 3px; }
/* biscione: the underline sharpens serpent-blue on hover */
.theme-inter-milan a:hover { text-decoration-thickness: 2px; text-decoration-color: oklch(0.80 0.10 255); }
.theme-inter-milan ::selection { background: oklch(0.543 0.171 260.5); color: oklch(1 0 0); }
.theme-inter-milan input, .theme-inter-milan select, .theme-inter-milan textarea { background: oklch(0.16 0.03 268); }
.theme-inter-milan input:focus-visible, .theme-inter-milan select:focus-visible, .theme-inter-milan textarea:focus-visible { outline: 2px solid oklch(0.62 0.16 259); outline-offset: 1px; }
.theme-inter-milan kbd { background: oklch(0.16 0.03 268); border: 1px solid var(--line); border-bottom: 3px solid oklch(0.543 0.171 260.5); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-inter-milan ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-inter-milan ::-webkit-scrollbar-track { background: oklch(0.16 0.03 268); }
.theme-inter-milan ::-webkit-scrollbar-thumb { background: linear-gradient(180deg, oklch(0.55 0.17 260), oklch(0.35 0.10 265)); border-radius: 5px; border: 2px solid oklch(0.16 0.03 268); }
.theme-inter-milan ::-webkit-scrollbar-thumb:hover { background: oklch(0.62 0.16 259); }
.theme-inter-milan .label-caps { color: var(--accent-2); }
/* nerazzurri shirt stripes on framed panels */
.theme-inter-milan .themed-border { border-image: repeating-linear-gradient(180deg, oklch(0.45 0.16 262) 0 8px, oklch(0.13 0.02 268) 8px 16px) 1; }
.theme-inter-milan button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-inter-milan.alt-mode {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.988 0.004 271.4);
  --surface-2: oklch(0.958 0.010 267.4);
  --fg: oklch(0.205 0.051 277.6);
  --fg-muted: oklch(0.500 0.050 277.3);
  --accent: oklch(0.394 0.138 264.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.180 0.043 277.1);
  --line: oklch(0.916 0.016 270.0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: repeating-linear-gradient(90deg, oklch(0.35 0.09 265 / 10%) 0 2px, transparent 2px 26px);
}
.theme-inter-milan.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #1e3f8f; }
.theme-inter-milan.alt-mode input, .theme-inter-milan.alt-mode select, .theme-inter-milan.alt-mode textarea { background: oklch(1 0 0); border: 1px solid var(--line); }
.theme-inter-milan.alt-mode kbd { background: var(--surface-2); color: var(--fg); }
.theme-inter-milan.alt-mode a { color: var(--accent); }
.theme-inter-milan.alt-mode ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-inter-milan.alt-mode ::-webkit-scrollbar-thumb { border-color: var(--surface-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
